      const calc=ev=>{const mx=cx+sx*w/2+(ev.clientX-x0)*sc,my=cy+sy*h/2+(ev.clientY-y0)*sc;const minW=c.w*0.03,minH=c.h*0.03;let nw=Math.max(minW,sx*(mx-fx)),nh=Math.max(minH,sy*(my-fy));nw=Math.min(nw,sx>0?c.x+c.w-fx:fx-c.x);nh=Math.min(nh,sy>0?c.y+c.h-fy:fy-c.y);return {nw,nh,ncx:fx+sx*nw/2,ncy:fy+sy*nh/2};};
      const move=ev=>{const q=calc(ev);rub.setAttribute('x',q.ncx-q.nw/2);rub.setAttribute('y',q.ncy-q.nh/2);rub.setAttribute('width',q.nw);rub.setAttribute('height',q.nh);};
