    const pv=$('#figImgPreview');let down=null;pv.addEventListener('pointerdown',e=>{const cb=e.target.closest('[data-cellbox]');down=cb&&!figImgState.tool&&!e.target.closest('[data-annot],[data-roih]')?+cb.dataset.cellbox:null;});
