  $('#figImgAutoLab').onclick=()=>{const j=figImgState.spec;if(j.type==='blot'){toast('ラベルの自動入力はグリッドで使えます');return;}let n=0;(j.images||[]).forEach(im=>{if(im.label)return;const t=figImgAutoLabel(im);if(t){im.label=t;n++;}});figImgFillList();figImgSync();toast(n?`${n} 枚にラベルを入れました（チャネル名・ファイル名から。直すときは各行の文字を書き換え）`:'空のラベルはありません');};
  swPick($('#figImgDlg .figLeft'),(k,i,v)=>{const j=figImgState.spec;if(k==='colColor'){j.colColors=j.colColors||[];while(j.colColors.length<=i)j.colColors.push('');j.colColors[i]=v&&v.toLowerCase()!=='#000000'?v:'';figImgFillColColors();figImgSync();}else if(k==='sbColor'){j.scale=j.scale||{};j.scale.color=v||'white';figImgFillColColors();figImgSync();}});
