  $('#figImgAnnots').addEventListener('change',e=>{const el=e.target.closest('[data-ak]');if(!el)return;const a=(figImgState.spec.annots||[])[+el.dataset.k];if(!a)return;const k=el.dataset.ak;if(k==='text'){a.text=el.value;if(!el.value){figImgState.spec.annots.splice(+el.dataset.k,1);figImgState.annotSel=null;}}else if(k==='size'){if(a.t==='inset')a.size=+el.value;else if(+el.value===1)delete a.size;else a.size=+el.value;}else if(k==='w'||k==='h'){const v=Math.max(3,Math.min(100,+el.value||25))/100;a[k]=+v.toFixed(3);}else if(k==='shape'){if(el.value==='circle')a.shape='circle';else delete a.shape;}else if(k==='dash'){if(el.value==='0')a.dash=false;else delete a.dash;}else if(k==='at'){a.at=el.value;}else if(k==='dir'){if(+el.value===225)delete a.dir;else a.dir=+el.value;}figImgSync();});
